"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";

const navItems = [
  { label: "Overview", href: "/dashboard", icon: "📊" },
  { label: "Inventory", href: "/dashboard/inventory", icon: "📦" },
  { label: "Purchases", href: "/dashboard/purchases", icon: "🛒" },
  { label: "Selling Price", href: "/dashboard/selling-price", icon: "💰" },
  { label: "Reports", href: "/dashboard/reports", icon: "📄" },
  { label: "Settings", href: "/dashboard/settings", icon: "⚙️" }
];

export default function DashboardSidebar() {
  const pathname = usePathname();

  return (
    <aside className="hidden w-64 flex-col gap-6 border-r border-border bg-card/50 p-6 text-foreground lg:flex">
      <div>
        <p className="text-sm font-semibold uppercase tracking-[0.3em] text-primary">
          Dashboard
        </p>
        <h2 className="mt-2 text-xl font-semibold">Shopkeeper Helper</h2>
      </div>
      <nav className="flex flex-col gap-2 text-sm">
        {navItems.map((item) => {
          const isActive = pathname === item.href;
          return (
            <Link
              key={item.href}
              href={item.href}
              className={`flex items-center gap-3 rounded-xl px-3 py-2 transition ${
                isActive 
                  ? "bg-primary/20 text-primary font-semibold" 
                  : "hover:bg-border/50"
              }`}
            >
              <span>{item.icon}</span>
              <span>{item.label}</span>
            </Link>
          );
        })}
      </nav>
      <div className="mt-auto rounded-2xl border border-border bg-card p-4 text-xs text-foreground">
        <p className="font-semibold text-primary">💡 Pro Tip</p>
        <p className="mt-2 text-muted">Track price changes over time to optimize your profit margins.</p>
      </div>
    </aside>
  );
}
